import Foundation
import Testing
import ZTronAssetModel
import ZTronAssetTestSupport

@testable import ZTronAssetStorage

/// The prior art's layout on the fake volume (R-STO-11): the committed `Tests/Fixtures/legacy-v0/` tree (generated by
/// running the prior art's own `CDNLocalStore`, see its README) or a hand-made one.
enum LegacyFixture {
    /// `Tests/Fixtures/legacy-v0/CDNAssets` in this repository.
    static func fixtureRoot(filePath: String = #filePath) -> URL {
        URL(fileURLWithPath: filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/legacy-v0/CDNAssets", isDirectory: true)
    }

    /// Every file of the committed fixture tree, by path relative to its root.
    static func fixtureFiles() throws -> [String: Data] {
        let root = LegacyFixture.fixtureRoot()
        var files: [String: Data] = [:]
        let enumerator = FileManager.default.enumerator(at: root, includingPropertiesForKeys: [.isRegularFileKey])
        while let url = enumerator?.nextObject() as? URL {
            guard (try url.resourceValues(forKeys: [.isRegularFileKey])).isRegularFile == true else {
                continue
            }
            let relative = String(url.standardizedFileURL.path.dropFirst(root.standardizedFileURL.path.count + 1))
            files[relative] = try Data(contentsOf: url)
        }
        return files
    }

    /// The fixture's manifest entries (its `manifest.json`, the prior art's cache of `v2-checksum-change.json`).
    static func entries() throws -> [ManifestEntry] {
        let data = try #require(try LegacyFixture.fixtureFiles()["manifest.json"])
        return try ManifestDecoder.decode(data).entries
    }

    /// A disk holding `files` (relative paths) under the legacy root, every item durable.
    @available(macOS 15.0, iOS 18.0, *)
    static func disk(_ files: [String: Data], root: URL = CleanupFixture.legacyRoot, base: DiskImage = DiskImage(), links: [(String, String)] = []) throws -> DiskImage {
        let fileSystem = FakeFileSystem(disk: base, time: ManualTimeSource())
        for (relative, bytes) in files.sorted(by: { $0.key < $1.key }) {
            let url = root.appendingPathComponent(relative)
            try LegacyFixture.makeDirectories(url.deletingLastPathComponent(), on: fileSystem)
            try fileSystem.write(bytes, to: url, mode: .truncate)
        }
        for (relative, destination) in links {
            let url = root.appendingPathComponent(relative)
            try LegacyFixture.makeDirectories(url.deletingLastPathComponent(), on: fileSystem)
            try fileSystem.createSymbolicLink(at: url, destination: destination)
        }
        var disk = fileSystem.survivingDisk()
        disk.makeDurable()
        return disk
    }

    /// Creates `directory` and its missing ancestors on `fileSystem`.
    @available(macOS 15.0, iOS 18.0, *)
    static func makeDirectories(_ directory: URL, on fileSystem: FakeFileSystem) throws {
        var missing: [URL] = []
        var current = directory
        while try fileSystem.itemInfo(at: current) == nil {
            missing.append(current)
            current = current.deletingLastPathComponent()
        }
        for url in missing.reversed() {
            try fileSystem.createDirectory(at: url)
        }
    }

    /// The prior art's path of `entry` relative to the legacy root (`CDNLocalStore.localURL(for:)`).
    static func relativePath(_ entry: ManifestEntry) -> String {
        let directories = entry.localPathComponents.isEmpty
            ? Array(entry.identifier.rawValue.split(separator: ".").map(String.init).dropLast())
            : entry.localPathComponents
        return (directories + ["\(entry.resolvedFileName).\(entry.fileExtension)"]).joined(separator: "/")
    }

    /// A legacy `manifest.json` for `entries` (the prior art's `JSONEncoder` shape: seven keys, optional ones omitted).
    static func manifestJSON(_ entries: [ManifestEntry]) throws -> Data {
        struct Legacy: Encodable {
            let identifier: String
            let fileExtension: String
            let remotePath: String
            let localPathComponents: [String]
            let localFileName: String?
            let byteSize: Int64?
            let checksum: String?
        }
        return try JSONEncoder().encode(entries.map {
            Legacy(
                identifier: $0.identifier.rawValue,
                fileExtension: $0.fileExtension,
                remotePath: $0.remotePath,
                localPathComponents: $0.localPathComponents,
                localFileName: $0.localFileName,
                byteSize: $0.byteSize,
                checksum: $0.checksum?.hex
            )
        })
    }

    /// A legacy `local-checksums.json`.
    static func checksumsJSON(_ checksums: [String: String]) throws -> Data {
        try JSONEncoder().encode(checksums)
    }

    /// A store over the fixture tree with legacy migration on and `stamp` in the fake defaults.
    @available(macOS 15.0, iOS 18.0, *)
    static func harness(
        files: [String: Data],
        stamp: String? = "1.4+77",
        links: [(String, String)] = [],
        crashBefore: Int? = nil,
        mode: CrashMode = .processKill,
        defaults: FakeLegacyDefaults? = nil,
        time: ManualTimeSource = ManualTimeSource()
    ) throws -> (CoreHarness, FakeLegacyDefaults) {
        let defaults = defaults ?? FakeLegacyDefaults(values: stamp.map { [CleanupFixture.legacyKey: $0] } ?? [:])
        let harness = CoreHarness.cleanup(
            disk: try LegacyFixture.disk(files, links: links),
            legacy: CleanupFixture.legacyPolicy,
            defaults: defaults,
            crashBefore: crashBefore,
            mode: mode,
            time: time
        )
        return (harness, defaults)
    }
}
